let serverBackupRunning=false;
let serverBackupState={phone:'',status:'idle',at:'',error:''},serverBackupOpenPending=false;
function backupText(text){return typeof featureText==='function'?featureText(text):text}
function backupStateForAccount(){if(serverBackupState.phone!==accountPhone)serverBackupState={phone:accountPhone,status:'idle',at:'',error:''};return serverBackupState}
function serverBackupTime(at){return new Intl.DateTimeFormat(typeof uiLocale==='function'?uiLocale():'en-US',{timeZone:'Asia/Dhaka',dateStyle:'medium',timeStyle:'short',hour12:true}).format(new Date(at))}
function serverBackupButtonMarkup(){const state=backupStateForAccount();return '<div class="server-backup-area"><button type="button" id="server-backup" class="server-backup-button'+(state.status==='complete'?' is-complete':'')+'"'+(state.status==='loading'?' disabled aria-busy="true"':'')+'><span class="server-backup-fill" aria-hidden="true"></span><span class="server-backup-icon" aria-hidden="true">'+(typeof profileIcon==='function'?profileIcon('upload'):'')+'</span><span class="server-backup-label">'+backupText(state.status==='loading'?'ব্যাকআপ হচ্ছে…':state.status==='complete'?'ব্যাকআপ সম্পন্ন':'সার্ভারে ব্যাকআপ নিন')+'</span><span class="server-backup-check" aria-hidden="true">✓</span></button><p id="server-backup-status" class="server-backup-status" role="status">'+esc(state.error||(state.at?backupText('সর্বশেষ ব্যাকআপ')+' · '+serverBackupTime(state.at):backupText('অ্যাপ খুললে স্বয়ংক্রিয় ব্যাকআপ হবে। গত ৪৮ ঘণ্টার কপি থাকবে।')))+'</p><button type="button" id="server-backup-history" class="server-backup-history">সার্ভারের ব্যাকআপগুলো দেখুন</button></div>'}
function updateServerBackupUI(){const state=backupStateForAccount(),button=document.querySelector('#server-backup'),status=document.querySelector('#server-backup-status');if(!button)return;button.disabled=state.status==='loading';button.classList.toggle('is-complete',state.status==='complete');button.classList.toggle('is-loading',state.status==='loading');button.setAttribute('aria-busy',String(state.status==='loading'));button.querySelector('.server-backup-label').textContent=backupText(state.status==='loading'?'ব্যাকআপ হচ্ছে…':state.status==='complete'?'ব্যাকআপ সম্পন্ন':'সার্ভারে ব্যাকআপ নিন');if(status)status.textContent=state.error||(state.at?backupText('সর্বশেষ ব্যাকআপ')+' · '+serverBackupTime(state.at):backupText('অ্যাপ খুললে স্বয়ংক্রিয় ব্যাকআপ হবে। গত ৪৮ ঘণ্টার কপি থাকবে।'))}
async function performServerBackup(source='manual'){if(!accountPhone)return false;const state=backupStateForAccount(),phone=accountPhone;if(state.status==='loading')return false;state.error='';if(accountBusy){state.status='waiting';state.error=backupText('হিসাব সংরক্ষণ শেষ হলে ব্যাকআপ নেওয়া যাবে।');updateServerBackupUI();return false}if(typeof offlineState!=='undefined'&&offlineState?.pending&&typeof syncOfflineChanges==='function')await syncOfflineChanges();if(accountPhone!==phone)return false;if((typeof navigator!=='undefined'&&navigator.onLine===false)||(typeof offlineState!=='undefined'&&offlineState?.pending)||(typeof syncConflict!=='undefined'&&syncConflict)){state.status='waiting';state.error=backupText('ইন্টারনেট ও তথ্যের সিঙ্ক সম্পন্ন হলে সার্ভারে ব্যাকআপ হবে।');updateServerBackupUI();return false}state.status='loading';updateServerBackupUI();try{const result=await accountAPI('backups','POST',{source,revision:accountRevision});if(accountPhone!==phone)return false;state.status='complete';state.at=result.backup.at;serverBackupOpenPending=false;return true}catch(error){if(accountPhone===phone){state.status='error';state.error=backupText('সার্ভারে ব্যাকআপ হয়নি।')+' '+backupText(error.message)}return false}finally{if(accountPhone===phone)updateServerBackupUI()}}
async function requestServerBackup(source='manual'){if(serverBackupRunning)return false;serverBackupRunning=true;const phone=accountPhone;try{return await performServerBackup(source)}finally{serverBackupRunning=false;if(accountPhone&&phone!==accountPhone)retryPendingServerBackup()}}
function autoServerBackupOnOpen(){serverBackupOpenPending=true;return requestServerBackup('auto')}
function retryPendingServerBackup(){if(!serverBackupRunning&&serverBackupOpenPending&&accountPhone&&!accountBusy&&!(typeof offlineState!=='undefined'&&offlineState?.pending)&&!(typeof syncConflict!=='undefined'&&syncConflict)&&!(typeof navigator!=='undefined'&&navigator.onLine===false))void requestServerBackup('auto')}
function bindServerBackups(){const button=document.querySelector('#server-backup');if(button)button.onclick=()=>requestServerBackup('manual');const history=document.querySelector('#server-backup-history');if(history)history.onclick=openServerBackupHistory;updateServerBackupUI()}
async function openServerBackupHistory(){const dialog=featureDialog(backupText('সার্ভারের ব্যাকআপ'),'<p class="muted">গত ৪৮ ঘণ্টার ব্যাকআপ এখানে পাওয়া যাবে।</p><div class="server-backup-list"></div><button type="button" class="server-backups-more">আরও দেখুন</button>'),list=dialog.querySelector('.server-backup-list'),more=dialog.querySelector('.server-backups-more');let cursor=null,count=0;async function load(){more.disabled=true;try{const page=await accountAPI('backups'+(cursor?'?cursor='+encodeURIComponent(cursor):''));count+=page.items.length;list.insertAdjacentHTML('beforeend',page.items.map(item=>'<article class="server-backup-record"><div><strong>'+esc(serverBackupTime(item.at))+'</strong><small>'+backupText(item.source==='auto'?'স্বয়ংক্রিয় ব্যাকআপ':'ম্যানুয়াল ব্যাকআপ')+'</small></div><button type="button" data-backup-id="'+esc(item.id)+'">ডাউনলোড</button></article>').join(''));if(!count)list.innerHTML='<p class="muted">এখনও কোনো সার্ভার ব্যাকআপ নেই।</p>';cursor=page.next;more.hidden=!cursor;list.querySelectorAll('[data-backup-id]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const result=await accountAPI('backups/'+encodeURIComponent(button.dataset.backupId));download('DailyTally-server-backup-'+result.backup.at.replace(/[:.]/g,'-')+'.json',JSON.stringify(result.data,null,2),'application/json')}catch(error){featureError(dialog,error)}finally{button.disabled=false}})}catch(error){featureError(dialog,error)}finally{more.disabled=false}}more.onclick=load;await load()}
if(typeof window!=='undefined')window.addEventListener('online',()=>retryPendingServerBackup());
if(typeof document.addEventListener==='function')document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')serverBackupOpenPending=true;else if(document.visibilityState==='visible')retryPendingServerBackup()});
